from mpmath import mp, jtheta, mpc, mpf

# Test 1: jtheta(4, mpc(2479 + 1020j), mpf('1e-2141')) at default precision
try:
    result1 = jtheta(4, mpc(2479 + 1020j), mpf('1e-2141'))
    probe("jtheta(4, mpc(2479 + 1020j), mpf('1e-2141')) at default precision", result1)
except Exception as e:
    probe_exception("jtheta(4, mpc(2479 + 1020j), mpf('1e-2141')) at default precision", e)

# Test 2: jtheta(4, mpc(2479 + 1020j), mpf('1e-2141'), 3) at default precision
try:
    result2 = jtheta(4, mpc(2479 + 1020j), mpf('1e-2141'), 3)
    probe("jtheta(4, mpc(2479 + 1020j), mpf('1e-2141'), 3) at default precision", result2)
except Exception as e:
    probe_exception("jtheta(4, mpc(2479 + 1020j), mpf('1e-2141'), 3) at default precision", e)

# Test 3: mp.extraprec(10000)(jtheta)(4, mpc(2479 + 1020j), mpf('1e-2141')) as high-precision reference
try:
    result3 = mp.extraprec(10000)(jtheta)(4, mpc(2479 + 1020j), mpf('1e-2141'))
    probe("mp.extraprec(10000)(jtheta)(4, mpc(2479 + 1020j), mpf('1e-2141')) as high-precision reference", result3)
except Exception as e:
    probe_exception("mp.extraprec(10000)(jtheta)(4, mpc(2479 + 1020j), mpf('1e-2141')) as high-precision reference", e)

